import React from 'react';
import '../App.css';
import { Button } from './Button';
import './HeroSection.css';
import {useState,useEffect} from 'react';

function HeroSection(props) {

  const imgs = ["/baysallar/images/home/1.jpg", "/baysallar/images/home/2.jpg", "/baysallar/images/home/3.jpg"]
  const [img, setImg] = useState("")
  let n = 0;


  const cacheImages = async (images) => {
    const promises = await images.map(image => {
      return new Promise(function (resolve, reject) {
        const imgObj = new Image();

        imgObj.src = image;
        imgObj.onload = resolve();
        imgObj.onerror = reject();
        console.log(imgObj.src)
      });
    });
    console.log("images loaded")
    let imagess = await Promise.all(promises);
    console.log(imagess)
    startAnimation();
    props.setLoading(false);
  }
  useEffect(() => {
    cacheImages(imgs);  
  }, []);

  const startAnimation = () => {

    const interval = setInterval(() => {
      setImg(imgs[n % imgs.length]);
      n += 1;
    }, 3000);
    
    return () => clearInterval(interval);
  };

  return (
    <div className='hero-container' id="anasayfa" style={{backgroundImage: "url("+img+")"}}>
      <div className='overlay'> </div>
      <h1 className='over'>Mobilya - Dekorasyon</h1>
      <p className='over'>Evinizi birlikte oluşturalım!</p>
      <div className='over hero-btns'>
        <Button
          className='btns'
          buttonStyle='btn--outline'
          buttonSize='btn--large'
          href="/urunler"
        >
          Ürün Çeşitleri
        </Button>
        <Button
          className='btns'
          buttonStyle='btn--primary'
          buttonSize='btn--large'
          href="/iletisim"
        >
          Bize Ulaşın
        </Button>
      </div>
    </div>
  );
}

export default HeroSection;
